 void RefreshRound24(){tempGridMessage.Visibility=Mode=="grid"&&Files.Count==0&&string.Equals(Folder,TempFolder,StringComparison.OrdinalIgnoreCase)?Visibility.Visible:Visibility.Collapsed;bool empty=Mode=="viewer"&&current==null;startupPage.Visibility=empty?Visibility.Visible:Visibility.Collapsed;bool compact=Config.HideQuickStart||root.ActualWidth<680||root.ActualHeight<420;foreach(UIElement child in startupPage.Children)child.Visibility=ReferenceEquals(child,startupLogo)||!compact?Visibility.Visible:Visibility.Collapsed;emptyFolderLine.Visibility=emptyFolderPath.Visibility=!compact&&hasFolder?Visibility.Visible:Visibility.Collapsed;emptyFolderPath.Text=hasFolder?Folder:"";if(!Config.AutoHideCursor)View.Cursor=Cursors.Arrow;if(Mode=="board")UpdateTitle();if(Config.SlideshowTimer)View.InvalidateVisual();}
