 void ToggleSelectAll(){var selectable=Enumerable.Range(FolderTileCount,GridPaths.Count-FolderTileCount).Where(i=>!GridHoles.Contains(GridPaths[i])).ToHashSet();if(View.Selected.SetEquals(selectable))View.Selected.Clear();else View.Selected=selectable;View.InvalidateVisual();}
 void ArrangeBoard(string action){var selected=View.BoardSelection.Where(View.Board.Contains).OrderBy(i=>i.ImportOrder).ToArray();if(selected.Length<2)return;View.Snapshot();if(action.StartsWith("Normalize")){bool width=action=="Normalize width";double largest=selected.Max(i=>width?i.Rect.Width:i.Rect.Height);foreach(var i in selected){var r=i.Rect;double factor=largest/(width?r.Width:r.Height);i.Rect=new Rect(r.X+r.Width*(1-factor)/2,r.Y+r.Height*(1-factor)/2,r.Width*factor,r.Height*factor);}}else{bool row=action=="Align in a row";bool reverse=row?rowReverse:columnReverse;if(reverse)Array.Reverse(selected);if(row)rowReverse=!rowReverse;else columnReverse=!columnReverse;var bounds=selected.Select(i=>i.Rect).Aggregate(Rect.Union);double length=selected.Sum(i=>row?i.Rect.Width:i.Rect.Height)+Config.CollageGap*(selected.Length-1);double cursor=(row?bounds.X+bounds.Width/2:bounds.Y+bounds.Height/2)-length/2;foreach(var i in selected){var r=i.Rect;i.Rect=row?new Rect(cursor,bounds.Y+(bounds.Height-r.Height)/2,r.Width,r.Height):new Rect(bounds.X+(bounds.Width-r.Width)/2,cursor,r.Width,r.Height);cursor+=(row?r.Width:r.Height)+Config.CollageGap;}}View.InvalidateVisual();}
