 void PositionMenu(){if(Files.Count==0)return;var w=Ui.Dialog(this,"Go to image",300,180);var p=new StackPanel{Margin=new Thickness(12)};p.Children.Add(Ui.Label("Image position (1–"+Files.Count+")",12));var input=Ui.Input((Index+1).ToString());p.Children.Add(input);var row=new WrapPanel();void Go(){if(int.TryParse(input.Text,out int n)&&n>=1&&n<=Files.Count){w.Close();Run(()=>ShowIndex(n-1));}}row.Children.Add(Ui.Button("Go",Go));row.Children.Add(Ui.Button("Cancel",w.Close));p.Children.Add(row);input.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Enter){e.Handled=true;Go();}};w.Content=p;w.Loaded+=(_,_)=>{input.Focus();input.SelectAll();};w.ShowDialog();}
